public static class Appearances
{

    /// <summary>
    /// All options for a part. (Server only.)
    /// </summary>
    /// <param name="part">'body', 'head', 'hair' or 'beard'.</param>
    /// <param name="gender">Optional: 'male' or 'female'.</param>
