    /// <summary>
    /// The beards a face can have. '' gives all beards, and an unknown face gives none. (Server only.)
    /// </summary>
    /// <param name="head">The face's name.</param>
    /// <param name="gender">Optional: the gender.</param>
    /// <returns>object[]</returns>
    public static JsValue Beards(object? head = null, object? gender = null) => Sdk.Call<JsValue>("players", "Appearances", "beards", Sdk.Optional(head), Sdk.Optional(gender));

    /// <summary>
    /// One option by name, or null. (Server only.)
    /// </summary>
    /// <param name="part">The part.</param>
    /// <param name="name">The option's name.</param>
    /// <param name="gender">Optional: the gender.</param>
    /// <returns>object | null</returns>
    public static JsValue Find(object? part, object? name, object? gender = null) => Sdk.Call<JsValue>("players", "Appearances", "find", part, name, Sdk.Optional(gender));

