/// <summary>
/// The game's status effects, your own buffs, and which kinds of effect the server decides. To give
/// and remove buffs on a player, use Player.addBuff and removeBuff. Events are playerBuffAdded,
/// playerBuffRemoved, and playerBuffBlocked, when a player's game tried to apply an effect of a
/// claimed kind. (Server only.)
/// </summary>
public static class Buffs
{

    /// <summary>
    /// The buff classes the server can decide with Buffs.claim, such as injury, heal, poison, alcohol
    /// and potion. (Server only.)
    /// </summary>
    public static string[] Classes
    {
        get => Sdk.Get<string[]>("players", "Buffs", "classes");
    }

    /// <summary>
    /// The game's buff tags, one of which Player.clearBuffs takes. (Server only.)
    /// </summary>
