    {
        get => Sdk.Get<string[]>("players", "Buffs", "tags");
    }

    /// <summary>
    /// Names a custom buff's modifiers can use: health, stamina, exhaust, hunger; the per-second rates
    /// healthRegeneration, hungerDrain and energyDrain; the game's maxStamina, carryCapacity,
    /// staminaRegeneration, runSpeed, attackSpeed, noise, visibility, conspicuousness, clothDirtying,
    /// charisma, strength, agility, vitality, speech and the progression tracks; and the switch
    /// noSprint. A new array each time. (Server only.)
    /// </summary>
    public static string[] Modifiers
    {
        get => Sdk.Get<string[]>("players", "Buffs", "modifiers");
    }

    /// <summary>
    /// A game or custom buff by name or GUID, or null: { name, class, aiTag, duration, custom,
    /// displayName, description }. A game buff has custom false and null texts. (Server only.)
    /// </summary>
    /// <param name="query">The buff's name or GUID.</param>
    /// <returns>object | null</returns>
    public static JsValue Find(object? query) => Sdk.Call<JsValue>("players", "Buffs", "find", query);

    /// <summary>
    /// Defines your own buff. Buffs.register(id, definition) returns its GUID, the same at each start.
    /// Registering the same definition again returns it, and a different definition under that id
    /// throws. Instances hold their stat modifiers while they last, take them back at the end, and fire
    /// playerCustomBuffApply, playerCustomBuffTick and playerCustomBuffRemove. The simpler
    /// Buffs.register(definition) returns an object instead. Either goes to Player.addBuff, removeBuff
    /// and hasBuff, and the status list shows it with a game buff's icon or, given an `image`, your
    /// own. (Server only.)
    /// </summary>
    /// <param name="idOrDefinition">The id: 1 to 128 letters, digits and : _ . -, and not a game buff's name. In the simple form, its definition: `name`, `icon`, `label`, `duration`, `effects` { stats, tickStats }, `tickSeconds` and `onTick(player, buff)`.</param>
    /// <param name="definition">`name`, required, the text the player sees; `description`; `visual`, required, the game buff whose icon it borrows; `image`, optional, a .dds your resource ships to clients (64 x 64, or an uncompressed 32-bit one clients scale to it), which the status list shows in place of the visual's icon; `duration`, seconds up to seven days, or -1, the default, for no end; `tickInterval`, 0, the default, for no ticks, or 0.1 to 86400 seconds; `stackable`, default false, with `maxStacks`, 1 to 16, default 1, and `refresh`, default true, replacing the oldest at the limit, while false ignores the new one; `modifiers`, { stat: points or { operation, value } }. For health, stamina, exhaust and hunger, 'add' or a plain number adds points, 'multiply' multiplies by value, 0 or more, and 'set' sets it. An instance works out its change from the player's reported value on landing and takes exactly that back at the end. healthRegeneration, hungerDrain and energyDrain give health, take hunger and add exhaust per second, a number of 0 or more, or 'add'. There is no modifier for maximum health or armor rating. The game's own modifiers, maxStamina, carryCapacity, staminaRegeneration, runSpeed, attackSpeed (multiply 0.8 swings at 80 % speed, as the game's arm wound), noise, visibility and conspicuousness (how NPCs hear, see and notice the player: the game's crouch is noise multiply 0.5, its Slim fit perk for armour noise multiply 0.8), clothDirtying (how fast walking dirties worn clothes, the game's own rate that Player.setGrimeRate scales; multiply 0 stops it), charisma, strength, agility, vitality, speech and the tracks stealth, horse_riding, fencing, thievery, alchemy, craftsmanship, drinking, survival, weapon_sword, heavy_weapons, marksmanship, weapon_large, weapon_unarmed, scholarship and houndmaster, take add, multiply or set. The game applies them once, however many stacks, while the buff is on the status list. noSprint: true keeps the player from sprinting while the buff lasts, as the game's leg wounds do; it takes true or false only.</param>
    /// <returns>string (the GUID) | { name, icon, label, duration, tickSeconds }</returns>
    public static JsValue Register(object? idOrDefinition, object? definition = null) => Sdk.Call<JsValue>("players", "Buffs", "register", idOrDefinition, Sdk.Optional(definition));

    /// <summary>
    /// Makes the server decide kinds of effect. Players' games stop applying buffs of these classes by
    /// themselves, each attempt firing playerBuffBlocked, and only Player.addBuff gives them. You can
    /// claim injury, heal, poison, perception, overeat, alcohol, potion, foodPoison, unconsciousness,
    /// hangover, satisfaction, perfume, punishment, forcedDrunkenness and plague. Pass [] to release
    /// all claims. Returns the claimed classes. (Server only.)
    /// </summary>
    /// <param name="classNames">The classes to claim.</param>
    /// <returns>string[]</returns>
    public static string[] Claim(object? classNames) => Sdk.Call<string[]>("players", "Buffs", "claim", classNames);
}

