/// <summary>
/// Players' inventories, held by the server. Each change is all or nothing, and returns { ok, code,
/// revision, items }. A refused change has ok false and a code, such as invalidItem, invalidAmount,
/// insufficientItems, inventoryCapacity, unknownItem or staleRevision. Passing `revision` refuses
/// the request if the inventory has changed. Rows are { id, item, name, amount, quality, health,
/// condition, equipped, metadata }. Events are playerInventoryReady, playerInventoryChanged and
/// playerItemUsed. Inventory.beforeCommit makes what players' own actions move wait for a
/// resource's verdict. On the client, Inventory.whenUsed takes over chosen items' actions on the
/// inventory screen.
/// </summary>
public static class Inventory
{

    /// <summary>
    /// All item classes in the game's catalogue, with id, name, nameKey, category, maximumQuality,
    /// quest, slot and model, the ground mesh, or '' if the tables give none. (Server only.)
    /// </summary>
    /// <returns>object[]</returns>
    public static JsValue Classes() => Sdk.Call<JsValue>("players", "Inventory", "classes");

    /// <summary>
    /// Scales how fast items wear, where 1 is the game's rate, 0 none and 2 twice as fast. A rate for
    /// an item, by table name or GUID, beats its category, such as meleeWeapon, missileWeapon, armor,
    /// helmet, hood, ammo or food, which beats `default`. Every drop in an item's condition counts, so
    /// the food rate scales how fast food spoils too. Repairs are never scaled. (Server only.)
    /// </summary>
    /// <param name="table">{ default, &lt;category&gt;, &lt;item&gt; }: the rates.</param>
    /// <returns>object</returns>
    public static JsValue SetWearRates(object? table = null) => Sdk.Call<JsValue>("players", "Inventory", "setWearRates", Sdk.Optional(table));

    /// <summary>
    /// The wear rates now set. (Server only.)
    /// </summary>
    /// <returns>object</returns>
    public static JsValue GetWearRates() => Sdk.Call<JsValue>("players", "Inventory", "getWearRates");

    /// <summary>
    /// The game's price for one unit, in money units, which are tenths of a groschen. `pristine` is at
    /// the best health its quality allows, and `current` at its own health. Null for an unknown class.
    /// (Server only.)
    /// </summary>
    /// <param name="item">The item class, by name or GUID.</param>
    /// <param name="metadata">Optional: its quality and health.</param>
    /// <returns>{ pristine, current } | null</returns>
    public static JsValue ItemPrice(object? item, object? metadata = null) => Sdk.Call<JsValue>("players", "Inventory", "itemPrice", item, Sdk.Optional(metadata));

    /// <summary>
    /// Renames an item in all players' games, along with other classes sharing its name, until the
    /// server stops. null restores the game's name. Returns the GUIDs renamed. (Server only.)
    /// </summary>
    /// <param name="item">The item class.</param>
    /// <param name="name">1 to 128 bytes, or null.</param>
    /// <returns>string[]</returns>
    public static string[] RenameItem(object? item, object? name) => Sdk.Call<string[]>("players", "Inventory", "renameItem", item, name);

    /// <summary>
    /// Overrides a class's combat values for all current and future players until the server stops, or
    /// restores them with null or {}. Values belong to the class, so all copies change and apply from
    /// the next hit. A set names only the stats it changes, and replaces the previous set entirely,
    /// while Items.override's weight, price, max and durability stay. A melee weapon takes attack,
    /// attackModStab, attackModSlash, attackModSmash, defense, strReq and agiReq. Armour, a helmet or a
    /// hood takes defenseStab, defenseSlash, defenseSmash, noise and strReq. A missile weapon takes
    /// power, defense, strReq and agiReq, while limbResistance is not supported yet and throws.
    /// Ammunition takes attackStab, attackSlash, attackSmash and powerMod. Throws a TypeError for an
    /// unknown class, a class with none of these, a name its kind lacks, or a value out of range.
    /// Returns true. (Server only.)
    /// </summary>
    /// <param name="item">The item class, by table name or GUID.</param>
    /// <param name="stats">The numbers by name, or null for the original values.</param>
    /// <returns>boolean</returns>
    public static bool OverrideStats(object? item, object? stats) => Sdk.Call<bool>("players", "Inventory", "overrideStats", item, stats);

    /// <summary>
    /// The combat numbers overrideStats set on a class, by name, or null if unchanged. The server does
    /// not read the game's numbers. Throws a TypeError for an unknown class. (Server only.)
    /// </summary>
    /// <param name="item">The item class, by table name or GUID.</param>
    /// <returns>Record&lt;string, number&gt; | null</returns>
    public static JsValue ItemStats(object? item) => Sdk.Call<JsValue>("players", "Inventory", "itemStats", item);

    /// <summary>
    /// A player's inventory as { revision, items, quickslots, ready }, or null. (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <returns>object | null</returns>
    public static JsValue Get(object? owner) => Sdk.Call<JsValue>("players", "Inventory", "get", owner);

    /// <summary>
    /// Adds units of one item class to the row with the same properties, or a new row. (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <param name="request">{ item, amount, metadata?, revision?, notify? }. `metadata` takes quality, health or condition, poison, poisonCharges, onEquipBuffs, and custom { name, description, data }, where data is a plain object up to 16 KiB as JSON, not text. Other values end with invalidMetadata. `transient: true` makes a row that leaves when its player disconnects, before playerDisconnect, so saving the inventory there leaves it out, suiting a sack over the head or a punishment prop. `notify: false` shows no 'You received' notice.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue Add(object? owner, object? request) => Sdk.Call<JsValue>("players", "Inventory", "add", owner, request);

    /// <summary>
    /// Takes units out of rows. (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <param name="request">{ units: [{ id, amount }], revision?, notify? }, with row ids from Inventory.get.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue Remove(object? owner, object? request) => Sdk.Call<JsValue>("players", "Inventory", "remove", owner, request);

    /// <summary>
    /// Changes only the named custom fields of a row, and null resets one. A row's own name and
    /// description show in its player's inventory and item panel for every kind of item (a renamed
    /// sword stays a sword for equipping and combat). (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <param name="request">{ id, name?, description?, data?, revision? }, where data is a plain object, not text.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue EditCustom(object? owner, object? request) => Sdk.Call<JsValue>("players", "Inventory", "editCustom", owner, request);

    /// <summary>
    /// Replaces a row's properties, keeping its id and amount. (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <param name="request">{ id, metadata, revision? }.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue EditRow(object? owner, object? request) => Sdk.Call<JsValue>("players", "Inventory", "editRow", owner, request);

    /// <summary>
    /// Replaces the whole inventory. Equipped pieces must fit on a body together, otherwise it returns
    /// invalidEquipment with `conflicts` saying why (as Player.equip). (Server only.)
    /// </summary>
    /// <param name="owner">The player.</param>
    /// <param name="request">{ items: rows, quickslots?, revision? }.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue Set(object? owner, object? request) => Sdk.Call<JsValue>("players", "Inventory", "set", owner, request);

    /// <summary>
    /// Moves exact units with their properties between inventories, all or nothing. (Server only.)
    /// </summary>
    /// <param name="source">The giving player.</param>
    /// <param name="target">The receiving player.</param>
    /// <param name="request">{ units: [{ id, amount }], notify? }.</param>
    /// <returns>{ ok, code, revision, items }</returns>
    public static JsValue Transfer(object? source, object? target, object? request) => Sdk.Call<JsValue>("players", "Inventory", "transfer", source, target, request);

    /// <summary>
    /// Makes what players' own actions do to inventories wait for this handler's verdict: taking up a
    /// ground item ('pickup'), dropping ('drop'), eating, drinking or applying an item or a pot's
    /// serving ('use'), a shop basket ('vendor'), a basket on another player's shelf ('trade'), taking
    /// from or putting into a container ('stashTake', 'stashPut'), taking from a body ('loot') and
    /// putting tack on or off a horse ('horseGear'). The handler receives the transaction { id, kind,
    /// player, revision, money, lines: [{ item, name, amount, metadata, row, price, from, to }] } with,
    /// by kind, groundItem, stash, owner, vendor, seller, horse or pot, and a verdict function. Return
    /// true or false, or a promise of either, or call verdict(true) or verdict(false, reason) later.
    /// Every handler must allow an action. A player's actions wait in line and commit one after
    /// another, against the inventories as they are then. An action not decided in 5 seconds is
    /// refused, and so is one whose handler throws. A refused action changes nothing, and the player's
    /// game shows what the server holds. The transaction's id is unique, also across server restarts,
    /// so a database outside can key its records by it: the playerInventoryChanged events the
    /// transaction's commit causes carry it as `transaction`, and playerInventoryTransaction follows
    /// them with whether it was applied or refused. Without a handler, actions commit at once and no
    /// transaction is made. Returns the handler's id. (Server only.)
    /// </summary>
    /// <param name="handler">Called with the transaction and the verdict function.</param>
    /// <returns>number</returns>
    public static double BeforeCommit(Delegate handler) => Sdk.Call<double>("players", "Inventory", "beforeCommit", handler);

    /// <summary>
    /// Removes a beforeCommit handler. A resource's handlers also go when it stops. (Server only.)
    /// </summary>
    /// <param name="id">The id from beforeCommit.</param>
    /// <returns>boolean</returns>
    public static bool StopBeforeCommit(object? id) => Sdk.Call<bool>("players", "Inventory", "stopBeforeCommit", id);

    /// <summary>
    /// Whether the game marks items as stolen. (Server only.)
    /// </summary>
    public static bool StolenMarks
    {
        get => Sdk.Get<bool>("players", "Inventory", "stolenMarks");
    }

    /// <summary>
    /// Turns the game's stolen marks, the red hand and merchants refusing stolen goods, on or off for
    /// all players. (Server only.)
    /// </summary>
    /// <param name="enabled">true or false.</param>
    /// <returns>void</returns>
    public static void SetStolenMarks(object? enabled) => Sdk.Call("players", "Inventory", "setStolenMarks", enabled);

    /// <summary>
    /// Client only. Takes over an item's actions on the inventory screen: 'secondary' to eat, drink or
    /// apply, 'primary' for the hint bar's action, and 'activate' for the equip toggle. The game then
    /// does nothing itself, and the handler receives { item, uid, id, revision, amount, action }, so
    /// consume anything on the server. The newest handler for an item instance beats one for its class.
    /// Returns the registration id. (Client only.)
    /// </summary>
    /// <param name="item">An item class, by name or GUID, a type from Items.register, or { uid } of one item.</param>
    /// <param name="handler">Called with the use.</param>
    /// <returns>number</returns>
    public static double WhenUsed(object? item, Delegate handler) => Sdk.Call<double>("players", "Inventory", "whenUsed", item, handler);

    /// <summary>
    /// Client only. Removes a whenUsed handler. (Client only.)
    /// </summary>
    /// <param name="id">The id from whenUsed.</param>
    /// <returns>boolean</returns>
    public static bool StopWhenUsed(object? id) => Sdk.Call<bool>("players", "Inventory", "stopWhenUsed", id);
}

/// <summary>
/// Your own item types, and changes to the game's items. A registered type is a miscellaneous item
/// that borrows an existing item's look, gets a stable GUID from its id, and works with all
/// inventory, stash and ground item calls. Overrides change a game item's weight, price, stats and
/// the most units a player can hold, for all players. The server's item-config.json in the
/// resources folder sets the same at startup: { "&lt;item GUID or name&gt;": { "weight": kg,
/// "price": price, "max": units, &lt;stat&gt;: value } }. The event playerCustomItemUse fires when
/// a usable type is used. (Server only.)
/// </summary>
public static class Items
{

    /// <summary>
    /// Creates a custom item type and returns its GUID. Registering it identically again returns the
    /// same GUID. The limit is 4096 types. (Server only.)
    /// </summary>
    /// <param name="id">Your id for it: letters, digits and :_-., up to 128 bytes.</param>
    /// <param name="definition">`name`, required, up to 256 bytes; `description`; `visual`, the miscellaneous item, crafting material or document it looks like; `model`, optional, a mesh of the prop catalogue as Prop.spawn takes it (such as 'manmade/common_furniture/bucket/bucket_a_a'), which it then lies on the ground as, shows in shops and Items.model returns, where a mesh the catalogue lacks throws a TypeError; `weight` in kg; `price`, a whole number of money units; `stackable`, default true; `usable` and `useLabel`, default 'Use', which offer a use action on the inventory screen; `icon`, an image your resource ships to clients.</param>
    /// <returns>string</returns>
    public static string Register(object? id, object? definition = null) => Sdk.Call<string>("players", "Items", "register", id, Sdk.Optional(definition));

    /// <summary>
    /// The mesh an item class has on the ground: its own model from the game's item tables, or for
    /// clothing and armour, the drop model. It is a path under objects/, or '' if the tables give none,
    /// as with DLC badges that only pin to a cap. Most of them, all .cgf files, are props too, so
    /// Prop.spawn can show an item alone, held still with physics 'none'. Throws a TypeError for an
    /// unknown class. (Server only.)
    /// </summary>
    /// <param name="item">The item class, by GUID or name in the game's item table.</param>
    /// <returns>string</returns>
    public static string Model(object? item) => Sdk.Call<string>("players", "Items", "model", item);

    /// <summary>
    /// What kind of item a class is. It has `category`, as from Inventory.classes, such as meleeWeapon,
    /// missileWeapon, armor or food. A weapon also has `weaponClass` from the game's table: dagger,
    /// sword, sabre, axe, longsword, mace, flail, halberd, shield, shieldBroken, huntingSword, torch,
    /// bow, crossbowLight, crossbowMedium, crossbowHeavy or rifle, otherwise null. It also has the
    /// attack modifiers `attackModSlash`, `attackModStab` and `attackModSmash`, otherwise 0. Use the
    /// modifiers to find out what a weapon can do, since the game's tables class a broken axe as a
    /// mace, with no slash. Null for an unknown class. A registered type is a misc item with no weapon
    /// class, and its `displayName` and `description` are the ones it was registered with (an empty
    /// description when it has none); for the game's own classes both are null. (Server only.)
    /// </summary>
    /// <param name="item">The item class, by GUID or name in the game's item table, or a registered type's id.</param>
    /// <returns>{ id, name, category, weaponClass, attackModSlash, attackModStab, attackModSmash, displayName, description } | null</returns>
    public static JsValue Info(object? item) => Sdk.Call<JsValue>("players", "Items", "info", item);

    /// <summary>
    /// Changes a game item for all players and returns its effective values. (Server only.)
    /// </summary>
    /// <param name="item">The item, by name or GUID.</param>
    /// <param name="fields">`weight`, `price`, `max` (units a player can hold), and stats for its category, such as armour defence, weapon attack, food health or `decayTime` (how long a food keeps before it spoils). Fields left out keep the game's value.</param>
    /// <returns>{ id, name, weight, price, max, stats, overridden }</returns>
    public static JsValue Override(object? item, object? fields) => Sdk.Call<JsValue>("players", "Items", "override", item, fields);

    /// <summary>
    /// Restores an item's game values, and returns whether it had an override. (Server only.)
    /// </summary>
    /// <param name="item">The item.</param>
    /// <returns>boolean</returns>
    public static bool ClearOverride(object? item) => Sdk.Call<bool>("players", "Items", "clearOverride", item);

    /// <summary>
    /// An item's values on this server, or null for an unknown item. (Server only.)
    /// </summary>
    /// <param name="item">The item, by name or GUID.</param>
    /// <returns>{ id, name, weight, price, max, stats, overridden } | null</returns>
    public static JsValue Effective(object? item) => Sdk.Call<JsValue>("players", "Items", "effective", item);

    /// <summary>
    /// The effective values of all overridden items. (Server only.)
    /// </summary>
    /// <returns>object[]</returns>
    public static JsValue Overrides() => Sdk.Call<JsValue>("players", "Items", "overrides");

    /// <summary>
    /// Sets the percentage of what players wear that counts toward their load.
    /// Player.setEquippedWeightPercent overrides it for one player. (Server only.)
    /// </summary>
    /// <param name="percent"></param>
    public static JsValue SetEquippedWeightPercent(object? percent) => Sdk.Call<JsValue>("players", "Items", "setEquippedWeightPercent", percent);

    /// <summary>
    /// The percentage of what players wear that counts toward their load, under the server's rule. 100
    /// by default. (Server only.)
    /// </summary>
    /// <returns>number</returns>
    public static double EquippedWeightPercent() => Sdk.Call<double>("players", "Items", "equippedWeightPercent");
}

/// <summary>
/// Lets players rob each other with the game's pickpocketing. The thief's game plays the minigame,
/// and the server decides whether a theft may start and learns how it ended. The events are
/// playerPickpocketStart, which can refuse, playerPickpocketCaught and playerPickpocketed. (Server
/// only.)
/// </summary>
public static class Pickpocketing
{

    /// <summary>
    /// Whether the game offers Rob on other players. (Server only.)
    /// </summary>
    public static bool Enabled
    {
        get => Sdk.Get<bool>("players", "Pickpocketing", "enabled");
    }

    /// <summary>
    /// Offers or removes Rob on other players, for all players. (Server only.)
    /// </summary>
    /// <param name="enabled">true or false.</param>
    /// <returns>void</returns>
    public static void SetEnabled(object? enabled) => Sdk.Call("players", "Pickpocketing", "setEnabled", enabled);

    /// <summary>
    /// Whether a player who catches a thief is told about it. (Server only.)
    /// </summary>
    public static bool VictimNotice
    {
        get => Sdk.Get<bool>("players", "Pickpocketing", "victimNotice");
    }

    /// <summary>
    /// The notice's text, where {thief} is replaced by the thief's name. For each language, use the
    /// Locales key 'pickpocket.victimNotice'. (Server only.)
    /// </summary>
    public static string VictimNoticeText
    {
        get => Sdk.Get<string>("players", "Pickpocketing", "victimNoticeText");
    }

    /// <summary>
    /// Turns the notice on or off, optionally with new text. (Server only.)
    /// </summary>
    /// <param name="enabled">true or false.</param>
    /// <param name="text">Optional: the notice's text.</param>
