/// <summary>
/// Shows one player's inventory as a shop on another's screen, using the game's shop screen. The
/// buyer sees the seller's items at `prices` or the server's price, and the seller's money as the
/// purse, but not their money items, quest items or worn gear. A basket is checked against both
/// inventories, and then both change together with the reason 'trade', or neither does. A trade
/// ends when the buyer closes the screen, either player leaves or is knocked out, Trade.close is
/// called, or the resource that opened it stops. (Server only.)
/// </summary>
public static class Trade
{

    /// <summary>
    /// Opens the seller's inventory as a shop on the buyer's screen, and returns the session id. It
    /// returns 0 if a player is gone or not ready, both are the same player, an inventory is missing,
    /// or a tradeOpen handler returns false. (Server only.)
    /// </summary>
    /// <param name="seller">The player whose items are for sale.</param>
    /// <param name="buyer">The player buying.</param>
    /// <param name="options">Optional { prices?: { item: price }, buys?: false, buyPrices?: { item: price } }. With `buys`, the buyer can also sell their items to the seller at `buyPrices` or the server's price.</param>
    /// <returns>number</returns>
    public static double Open(object? seller, object? buyer, object? options = null) => Sdk.Call<double>("players", "Trade", "open", seller, buyer, Sdk.Optional(options));

    /// <summary>
    /// Ends a trade. Returns false if it has already ended. (Server only.)
    /// </summary>
    /// <param name="sessionId">The session from Trade.open.</param>
    /// <returns>boolean</returns>
    public static bool Close(object? sessionId) => Sdk.Call<bool>("players", "Trade", "close", sessionId);

    /// <summary>
    /// The trade session the player is in as buyer or seller, or 0. (Server only.)
    /// </summary>
    /// <param name="player">The player.</param>
    /// <returns>number</returns>
    public static double ActiveSession(object? player) => Sdk.Call<double>("players", "Trade", "activeSession", player);
}

/// <summary>
/// Switches for the game's interactions, set for everyone here or for one player with
/// Player.setInteraction. Off until a resource turns them on: 'horseWhistle', the companion key's
/// whistle that calls the horse; 'playerTalk', Talk and focus chat on another player; and
/// 'trespass', being in private and prohibited areas with no HUD warning and the AI told not to
/// react. On by default: 'npcChatter', the barks and lines of NPCs; 'pointing', where the B key
/// points the player's arm where their camera looks, on all screens; 'cooking', the prompt and use
/// key at the game's fires; and 'smoking', the same at smokehouses and drying racks. 'npcTalk',
/// Talk on an NPC, and 'npcChat', focus chat on an NPC, can never be turned on, because the game's
/// NPC conversations crashed players' games. (Server only.)
/// </summary>
public static class Interactions
{

    /// <summary>
    /// All interaction names. (Server only.)
    /// </summary>
    public static string[] Names
    {
        get => Sdk.Get<string[]>("players", "Interactions", "names");
        set => Sdk.Set("players", "Interactions", "names", value);
    }

    /// <summary>
    /// Allows or forbids an interaction for all players. (Server only.)
    /// </summary>
    /// <param name="name">The interaction's name.</param>
    /// <param name="allowed">true or false.</param>
    /// <returns>void</returns>
    public static void Set(object? name, object? allowed) => Sdk.Call("players", "Interactions", "set", name, allowed);

    /// <summary>
    /// Whether an interaction is allowed for all players. (Server only.)
    /// </summary>
    /// <param name="name">The interaction's name.</param>
    /// <returns>boolean</returns>
    public static bool Get(object? name) => Sdk.Call<bool>("players", "Interactions", "get", name);
}

/// <summary>
/// Client only. The Player at this machine, or null until they are in the world. It has all the
/// client-side members of Player. (Client only.)
/// </summary>
public static class LocalPlayer
{
    /// <summary>The value now (it changes as the game reports).</summary>
    public static Kcds.Players.Player? Current => Sdk.Live<Kcds.Players.Player?>("players", "LocalPlayer");
}
